// Isolated accuracy study using production physical derivative matrices.
// No filtering or PDE evolution. Words are chronological: xxy = Dy Dx Dx.
#include "mfem.hpp"
#include "../src/curved_geometry.hpp"
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
using namespace mfem;
Vector Apply(const std::vector<DenseMatrix>& D,const Vector& u,const std::string& word){Vector v(u),z(u.Size());for(char c:word){D[c=='x'?0:1].Mult(v,z);v=z;}return v;}
double PowerDerivative(double s,int degree,int order){if(order>degree)return 0;double v=1;for(int j=0;j<order;++j)v*=degree-j;return v*std::pow(s,degree-order);}
// Exact derivatives of [T^{-1}(x)]^degree for T(s)=s+a*s*(1-s).
double InversePower(double x,double a,int degree,int order){double s=2*x/(1+a+std::sqrt((1+a)*(1+a)-4*a*x));double j=1+a-2*a*s;double d1=1/j,d2=2*a/std::pow(j,3),d3=12*a*a/std::pow(j,5);if(order==0)return PowerDerivative(s,degree,0);if(order==1)return PowerDerivative(s,degree,1)*d1;if(order==2)return PowerDerivative(s,degree,2)*d1*d1+PowerDerivative(s,degree,1)*d2;return PowerDerivative(s,degree,3)*d1*d1*d1+3*PowerDerivative(s,degree,2)*d1*d2+PowerDerivative(s,degree,1)*d3;}
double Exact(int field,const Vector& x,int nx,int ny,double a){double pi=std::acos(-1.);if(field==0)return std::pow(2.,nx)*std::pow(3.,ny)*std::sin(2*x(0)+3*x(1)+(nx+ny)*pi/2);if(field==1)return std::pow(8.,nx)*std::pow(6.,ny)*std::sin(8*x(0)+6*x(1)+(nx+ny)*pi/2);if(field==2)return std::pow(.5,ny)*std::exp(x(0)+.5*x(1));if(field==3)return (nx+ny==0)?1.:0.;return InversePower(x(0),a,2,nx)*InversePower(x(1),.7*a,0,ny)+InversePower(x(0),a,1,nx)*InversePower(x(1),.7*a,1,ny)+InversePower(x(0),a,0,nx)*InversePower(x(1),.7*a,2,ny);}
struct Row{int field;std::string word;double error=0,l1=0,linf=0,truth=0,truthmax=0,floor=0,excess=0,faceerror=0,facetruth=0,facemax=0;};
int main(int argc,char**argv){Mpi::Init(argc,argv);if(argc!=9){std::cerr<<"family n p amplitude basis map qextra evalextra\n";return 2;}std::string family=argv[1],basis=argv[5],mapping=argv[6];int n=std::stoi(argv[2]),p=std::stoi(argv[3]),extra=std::stoi(argv[7]),evalextra=std::stoi(argv[8]);double a=std::stod(argv[4]);
 Mesh mesh=Mesh::MakeCartesian2D(n,n,family=="tri"?Element::TRIANGLE:Element::QUADRILATERAL,true);mesh.SetCurvature(4);mesh.Transform([&](const Vector&s,Vector&x){x=s;if(mapping=="coupled"){double b=a*s(0)*(1-s(0))*s(1)*(1-s(1));x(0)+=b;x(1)+=.7*b;}else{x(0)+=a*s(0)*(1-s(0));x(1)+=.7*a*s(1)*(1-s(1));}});
 int bt=basis=="gll"?BasisType::GaussLobatto:(basis=="gl"?BasisType::GaussLegendre:BasisType::Positive);DG_FECollection fec(p,2,bt);FiniteElementSpace space(&mesh,&fec);
 std::vector<std::string> words={"x","y"};if(p>=2)for(auto w:{"xx","xy","yy"})words.push_back(w);if(p>=3)for(auto w:{"xxx","xxy","xyy","yyy"})words.push_back(w);std::vector<int> fields=mapping=="coupled"?std::vector<int>{0,1,2,3}:std::vector<int>{4,3};std::vector<Row> rows;for(int f:fields)for(auto&w:words)rows.push_back({f,w});
 std::vector<std::vector<Vector>> coeff(space.GetNE());double weak=0,minjac=1e100,volume=0,facesize=0;int qb=0;std::vector<double> input(5,0),unorm(5,0);
 for(int e=0;e<space.GetNE();++e){auto*fe=space.GetFE(e);auto*map=space.GetElementTransformation(e);int nd=fe->GetDof();qb=ofdg::detail::CurvedQuadratureOrder(p,*map);auto D=ofdg::detail::ProjectedPhysicalDerivatives(*fe,*map,qb+extra);const auto&rule=ofdg::detail::CurvedRule(fe->GetGeomType(),qb+16+evalextra);DenseMatrix M(nd);M=0.;Vector sh(nd),x;std::vector<Vector> rhs(5,Vector(nd));for(auto&v:rhs)v=0.;
 for(int q=0;q<rule.GetNPoints();++q){auto&ip=rule.IntPoint(q);map->SetIntPoint(&ip);map->Transform(ip,x);fe->CalcShape(ip,sh);double w=ip.weight*map->Weight();volume+=w;minjac=std::min(minjac,map->Jacobian().Det());AddMult_a_VVt(w,sh,M);for(int f:fields)rhs[f].Add(w*Exact(f,x,0,0,a),sh);}
 DenseMatrixInverse solve(M);std::vector<Vector> U(5,Vector(nd));for(int f:fields)solve.Mult(rhs[f],U[f]);coeff[e].resize(rows.size());
 for(int f:fields){for(int q=0;q<rule.GetNPoints();++q){auto&ip=rule.IntPoint(q);map->SetIntPoint(&ip);map->Transform(ip,x);fe->CalcShape(ip,sh);double w=ip.weight*map->Weight(),truth=Exact(f,x,0,0,a),v=sh*U[f];input[f]+=w*(v-truth)*(v-truth);unorm[f]+=w*truth*truth;}
 // Independent weak consistency check uses chain rule explicitly, rather than CalcPhysDShape.
 for(int j=0;j<2;++j){Vector b(nd),z(nd),mz(nd);b=0.;D[j].Mult(U[f],z);M.Mult(z,mz);DenseMatrix ds(nd,2);for(int q=0;q<rule.GetNPoints();++q){auto&ip=rule.IntPoint(q);map->SetIntPoint(&ip);fe->CalcShape(ip,sh);fe->CalcDShape(ip,ds);double v=0.;for(int i=0;i<nd;++i)for(int s=0;s<2;++s)v+=ds(i,s)*map->InverseJacobian()(s,j)*U[f](i);b.Add(ip.weight*map->Weight()*v,sh);}mz-=b;weak=std::max(weak,mz.Normlinf()/std::max(1.,b.Normlinf()));}}
 for(size_t ri=0;ri<rows.size();++ri){auto&r=rows[ri];int nx=0;for(char c:r.word)nx+=c=='x';int ny=r.word.size()-nx;coeff[e][ri]=Apply(D,U[r.field],r.word);Vector b(nd),best(nd);b=0.;for(int q=0;q<rule.GetNPoints();++q){auto&ip=rule.IntPoint(q);map->SetIntPoint(&ip);map->Transform(ip,x);fe->CalcShape(ip,sh);b.Add(ip.weight*map->Weight()*Exact(r.field,x,nx,ny,a),sh);}solve.Mult(b,best);
 for(int q=0;q<rule.GetNPoints();++q){auto&ip=rule.IntPoint(q);map->SetIntPoint(&ip);map->Transform(ip,x);fe->CalcShape(ip,sh);double w=ip.weight*map->Weight(),t=Exact(r.field,x,nx,ny,a),v=sh*coeff[e][ri],pr=sh*best,err=v-t;r.error+=w*err*err;r.l1+=w*std::abs(err);r.linf=std::max(r.linf,std::abs(err));r.truth+=w*t*t;r.truthmax=std::max(r.truthmax,std::abs(t));r.floor+=w*(pr-t)*(pr-t);r.excess+=w*(v-pr)*(v-pr);}}
 }
 // One-sided trace errors over every element boundary, interior faces counted on both sides.
 for(int f=0;f<mesh.GetNumFaces();++f){auto*tr=mesh.GetFaceElementTransformations(f);if(!tr)continue;const auto&ir=IntRules.Get(tr->GetGeometryType(),qb+16+evalextra);for(int q=0;q<ir.GetNPoints();++q){auto&ip=ir.IntPoint(q);tr->SetAllIntPoints(&ip);Vector x;tr->Face->Transform(ip,x);double w=ip.weight*tr->Face->Weight();for(int side=0;side<2;++side){int e=side?tr->Elem2No:tr->Elem1No;if(e<0)continue;facesize+=w;auto*fe=space.GetFE(e);Vector sh(fe->GetDof());fe->CalcShape(side?tr->GetElement2IntPoint():tr->GetElement1IntPoint(),sh);for(size_t ri=0;ri<rows.size();++ri){auto&r=rows[ri];int nx=0;for(char c:r.word)nx+=c=='x';double t=Exact(r.field,x,nx,r.word.size()-nx,a),err=sh*coeff[e][ri]-t;r.faceerror+=w*err*err;r.facetruth+=w*t*t;r.facemax=std::max(r.facemax,std::abs(err));}}}}
 if(minjac<=0||!std::isfinite(weak)||weak>1e-8){std::cerr<<"control failure "<<minjac<<" "<<weak;return 3;}
 std::cout<<"family,n,p,amplitude,basis,map,qextra,evalextra,field,derivative,error_l2,relative_l2,error_l1,sampled_linf,relative_sampled_linf,truth_l2,best_projection_l2,excess_over_projection_l2,input_error_l2,input_l2,scaled_l2,face_rms,face_relative_l2,face_sampled_linf,weak_residual,min_jacobian,volume,elements,dofs\n"<<std::setprecision(17);const char*names[]={"sine","shortwave","exponential","constant","represented_quadratic"};for(auto&r:rows){double truth=std::sqrt(r.truth);std::cout<<family<<','<<n<<','<<p<<','<<a<<','<<basis<<','<<mapping<<','<<extra<<','<<evalextra<<','<<names[r.field]<<','<<r.word<<','<<std::sqrt(r.error)<<','<<(truth>1e-12?std::sqrt(r.error)/truth:NAN)<<','<<r.l1<<','<<r.linf<<','<<(r.truthmax>1e-12?r.linf/r.truthmax:NAN)<<','<<truth<<','<<std::sqrt(r.floor)<<','<<std::sqrt(r.excess)<<','<<std::sqrt(input[r.field])<<','<<std::sqrt(unorm[r.field])<<','<<std::sqrt(r.error)*std::pow(1./n,r.word.size())/std::sqrt(unorm[r.field])<<','<<std::sqrt(r.faceerror/facesize)<<','<<(r.facetruth>1e-24?std::sqrt(r.faceerror/r.facetruth):NAN)<<','<<r.facemax<<','<<weak<<','<<minjac<<','<<volume<<','<<space.GetNE()<<','<<space.GetVSize()<<'\n';}
}
